export const HasNoAccessMessage = ({
  headTitle,
  noSalesButton,
}) => {
  const dispatch = useDispatch()
  const { setShowPricingModal, setTriggerRequestQuote } = useRestrictionContext()
  const [setOrgCsrf] = useState(false)
  const handleClick = async (triggerIntercom) => {
    if( triggerIntercom ) {
      showIntercom()
    }else{
      setTriggerRequestQuote(true)
      setShowPricingModal(true)
    }
    const orgCsrfData = await dispatch(getOrgCsrf())
    if(orgCsrfData) await setOrgCsrf(orgCsrfData)
    dispatch(changeCommonValue('isVisible_custom_popup', false, '...'))
  }
  return (
    <>
      {headTitle}
      {!noSalesButton && (
        <>
          <p>
            Please <a href='#!' onClick={() => handleClick()}>request a quote</a> to
            upgrade your plan and gain access to the account.{' '}
          </p>
          <Button onClick={() => handleClick(true)} type='primary'>
            Get in touch with sales
          </Button>
        </>
      )}
    </>
  )
}

