import React, { useState, useEffect } from 'react'
import { useSelector, useDispatch } from 'react-redux'
import { Button, Card, Row, Col, Avatar, Spin, message, Alert, Tooltip } from 'antd'
import classNames from 'classnames'
import ReactHtmlParser from 'react-html-parser'
import Router from 'next/router'
import { findLastIndex, findIndex, capitalize } from 'lodash'
import RandomColor from 'components/common/randomColor'
import {
  checkPlanStatus,
  getApps,
  getUsers,
  manageAppAccess,
  manageUserAccess,
} from 'redux/actions/accessManagement'
import NewRequestQuoteForm from 'components/features/setting/Quote/PlanBasedPricingPopup/NewRequestQuoteForm'
import ReactLoader from 'components/common/reactLoading'
import { getAppDropdown } from 'redux/actions/appdropdown'
import { getOrgCsrf } from 'redux/actions/common'
import { showIntercom } from 'Utils/constants/index'
import CustomerSuccess from './DeveloperGuide/CustomerSuccess'
import Question from './question'
import IntegrateWrapper from './DeveloperGuide/IntegrateWrapper'

const dynamicAppUserTitle = (app, user, id) => {
  const text =
    id === 'app_select'
      ? `Your current plan includes ${app} app environments. `
      : `Your current plan includes ${user} user licenses.`
  return <h2>{text}</h2>
}
const Wrapper = ({ children }) => (
    <div className='display-table'>
      <div className='integrate-wrapper height-full'>
        <Card className='restrict-message-card'>{children}</Card>
      </div>
    </div>
  )
const SelectWrapper = ({
  children,
  subTitle,
  handleDone,
  disabled,
  totalAllowedAppsInPlan,
  totalAllowedUsersInPlan,
  btnTitle,
  loader,
  id,
  alertInfo,
}) => (
    <Spin spinning={loader} indicator={<ReactLoader />}>
      {dynamicAppUserTitle(totalAllowedAppsInPlan, totalAllowedUsersInPlan, id)}
      <p>{subTitle}</p>
      <Row gutter={[8, 8]}>{children}</Row>
      <Button disabled={disabled} onClick={(e) => handleDone(e)} type='primary'>
        {btnTitle}
      </Button>
      {alertInfo}
      <style>
        {`
          .active-card {
            border: 2px solid #3ADC91 !important;
          }
        `}
      </style>
    </Spin>
  )
const TrialPlan = ({
  toggleAppSelect,
  selectUserAction,
  selectAppAction,
  toggleUserLicense,
  loader,
  planStatusMessage,
}) => {
  let text
  const commonTxt =
    'which user licenses to activate if you have more than one user license available on your plan'
  if (selectUserAction && selectAppAction) {
    text = `which apps you would like to continue analyzing and ${commonTxt}`
  } else if (selectUserAction && !selectAppAction) {
    text = commonTxt
  } else if (!selectUserAction && selectAppAction) {
    text = `which apps you would like to continue analyzing`
  }
  return (
    <Wrapper loader={loader}>
      <Spin spinning={loader} indicator={<ReactLoader />}>
        <div className='downgrade-message'>
          {ReactHtmlParser(planStatusMessage)}
          {/* <p>
            To upgrade your account to access premium features, contact{' '}
            <a onClick={() => showIntercom()}>sales@uxcam.com</a>.
          </p> */}
          <p>{`During the next steps, you will be asked to select ${text}.`}</p>
          <Button
            type='primary'
            onClick={() => {
              selectUserAction && selectAppAction && toggleAppSelect(true)
              selectUserAction && !selectAppAction && toggleUserLicense(true)
              !selectUserAction && selectAppAction && toggleAppSelect(true)
            }}
          >
            Got it!
          </Button>
        </div>
      </Spin>
    </Wrapper>
  )
}
const UserSelect = ({
  loader,
  appTeam,
  disabled,
  activeEmail,
  handleDoneCaseUsers,
  totalAllowedAppsInPlan,
  totalAllowedUsersInPlan,
  handleUserEmailSelect,
  handleUserEmailDeselect,
}) => (
    <Wrapper loader={loader}>
      <div className='select-user-message'>
        <SelectWrapper
          loader={loader}
          disabled={disabled}
          subTitle="Please select which user licenses you would like to activate."
          handleDone={handleDoneCaseUsers}
          totalAllowedAppsInPlan={totalAllowedAppsInPlan}
          totalAllowedUsersInPlan={totalAllowedUsersInPlan}
          btnTitle="Done"
          key="user_select"
          id="user_select"
          alertInfo={
            <Alert
              message={
                <span>
                  *If you would like to change the account owner, please
                  contact our{' '}
                  <a onClick={() => showIntercom()}>Support team.</a>
                </span>
              }
              type='info'
            />
          }
        >
          {appTeam?.length ? (
            appTeam.map((team) => (
                <Col key={team.email}>
                  <Card
                    key={team.email}
                    onClick={() => {
                      if (team.isOwner) return
                      activeEmail.includes(team.email)
                        ? handleUserEmailDeselect(team.email)
                        : handleUserEmailSelect(team.email)
                    }}
                    className={classNames({
                      'active-card': activeEmail.includes(team.email),
                      'disabled-cursor': team.isOwner,
                    })}
                  >
                    <Avatar
                      shape='circle'
                      style={{
                        color: '#FFFFFF',
                        backgroundColor: RandomColor(team.email?.trim()),
                      }}
                    >
                      <span className="avatar-text-pop">
                        {capitalize(team.email?.trim().charAt(0))}
                      </span>{' '}
                    </Avatar>
                    <label className='name'>{team.name || '-'}</label>
                    <label className='mail'>{team.email}</label>
                    <label className='role'>{team.roleText}</label>
                  </Card>
                </Col>
              ))
          ) : (
            <></>
          )}
        </SelectWrapper>
      </div>
    </Wrapper>
  )
const AppSelect = ({
  apps,
  loader,
  planStatus,
  totalAllowedAppsInPlan,
  totalAllowedUsersInPlan,
  activeAppId,
  handleAppDeselect,
  handleAppSelect,
  disabled,
  handleDoneCaseApps,
  _getOrgCsrf,
  showHideQuoteModal,
}) => {
  const dispatch = useDispatch()
  return (
    <Wrapper loader={loader}>
      <div className='select-app-message'>
        <SelectWrapper
          loader={loader}
          disabled={disabled}
          subTitle="Please select the ones you would like to continue analyzing."
          handleDone={handleDoneCaseApps}
          planStatus={planStatus}
          totalAllowedAppsInPlan={totalAllowedAppsInPlan}
          totalAllowedUsersInPlan={totalAllowedUsersInPlan}
          btnTitle={!planStatus.selectUserAction ? 'Done' : 'Next'}
          key="app_select"
          id="app_select"
          alertInfo={
            <Alert
              message={
                <span>
                  *The app key for any apps that are not selected will remain
                  active and connected to your account, but we will discontinue
                  collecting sessions for those apps. The data collected during
                  your trial will be retained for the remainder of your data
                  retention period (1 month). If you would like to access these
                  apps, please{' '}
                  <a
                    onClick={async () => {
                      const orgCsrf = await dispatch(getOrgCsrf())
                      orgCsrf && (await _getOrgCsrf(orgCsrf))
                      showHideQuoteModal(true)
                    }}
                  >
                    request a quote
                  </a>{' '}
                  to upgrade your account.
                </span>
              }
              type='info'
            />
          }
        >
          {apps?.length ? (
            apps.map((app) => {
              const imgElement = app.image
              const appName = app.name
              return (
                <Col key={app['_id']}>
                  <Card
                    key={app['_id']}
                    onClick={() => {
                      activeAppId.includes(app['_id'])
                        ? handleAppDeselect(app['_id'])
                        : handleAppSelect(app['_id'])
                    }}
                    className={classNames({
                      'active-card': activeAppId.includes(app['_id']),
                    })}
                  >
                    {imgElement ? (
                      <img
                        src={imgElement}
                        onError={(e) => {
                          e.target.src = '/static/image-broken.png'
                        }}
                        alt='app_name'
                        width='65'
                        height='65'
                      />
                    ) : (
                      <Avatar
                        shape='square'
                        style={{
                          color: '#FFFFFF',
                          backgroundColor: RandomColor(appName.trim()),
                        }}
                      >
                        <span className="avatar-text-pop">
                          {capitalize(appName.trim().charAt(0))}
                        </span>{' '}
                      </Avatar>
                    )}
                    <Tooltip title={appName}>
                      <label>{appName}</label>
                    </Tooltip>
                  </Card>
                </Col>
              )
            })
          ) : (
            <></>
          )}
        </SelectWrapper>
      </div>
    </Wrapper>
  )
}
const AccessManagement = ({ hasNoAccess, hasNoAccessMessage }) => {
  const dispatch = useDispatch()
  const {
    currentAppReducer: currentApp,
    accessManagement,
    urlReducer,
  } = useSelector((state) => state)
  const orgId = urlReducer.orgId || currentApp.orgId
  const {planStatus} = accessManagement
  const {userList} = accessManagement
  const {appList} = accessManagement
  const planStatusMessage = planStatus?.message
  const appTeam = userList?.team
  const apps = appList?.apps
  const totalAllowedUsersInPlan = userList?.totalAllowedUsersInPlan
  const totalAllowedAppsInPlan = appList?.totalAllowedAppsInPlan
  const [isAppSelectVisible, toggleAppSelect] = useState(false)
  const [isUserLicenseVisible, toggleUserLicense] = useState(false)
  const [loader, setLoader] = useState(false)
  const [activeAppId, selectApp] = useState([])
  const [activeEmail, selectEmail] = useState([])
  const [questionPage, toogleQuestionPage] = useState(false)
  const [requestQuoteVisible, showHideQuoteModal] = useState(false)
  const [orgCsrf, _getOrgCsrf] = useState(false)

  const handleAppRouteChange = () => {
    setLoader(true)
    dispatch(getAppDropdown())
      .then((res) => {
        const {orgId} = currentApp
        const indexOrgId = findLastIndex(res, { orgId })
        const {apps} = res[indexOrgId]
        const indexAppId = findLastIndex(apps, { hasAccess: true })
        const __appId = indexAppId > -1 ? apps[indexAppId]['_id'] : apps[0]['_id']
        dispatch(checkPlanStatus(orgId))
        if (apps[indexAppId].isIntegrated) {
          Router.push(
            `/integration?parentType=overview&appId=${__appId}`,
            `/app/${__appId}/overview`
          )
        } else {
          Router.push(
            `/integration?parentType=integration&appId=${__appId}`,
            `/integration?appId=${__appId}`
          )
        }
        setLoader(false)
      })
      .catch((error) => setLoader(false))
  }
  const handleAppSelect = (appId) => selectApp([...activeAppId, appId])
  const handleAppDeselect = (appId) =>
    selectApp(activeAppId.filter((id) => appId !== id))
  const handleUserEmailSelect = (email) => selectEmail([...activeEmail, email])
  const handleUserEmailDeselect = (email) =>
    selectEmail(activeEmail.filter((id) => email !== id))
  const handleDoneCaseApps = (e) => {
    e.preventDefault()
    setLoader(true)
    dispatch(
      manageAppAccess({
        organizationId: orgId,
        selectedApps: activeAppId,
      })
    )
      .then((res) => {
        if (res.success) {
          message.success(res.message)
          if (planStatus.selectUserAction) {
            toggleAppSelect(false)
            toggleUserLicense(true)
            setLoader(false)
          } else handleAppRouteChange()
        } else {
          setLoader(false)
          if (res.response?.data?.error?.message) {
            message.error(res.response.data.error.message)
          }
          if (res.data?.error?.message) {
            message.error(res.data.error.message)
          }
          if (res.error?.selectedApps[0]) {
            message.error(res.error.selectedApps[0])
          }
        }
      })
      .catch((error) => setLoader(false))
  }
  const handleDoneCaseUsers = (e) => {
    e.preventDefault()
    setLoader(true)
    dispatch(
      manageUserAccess({
        organizationId: orgId,
        selectedUsers: activeEmail,
      })
    )
      .then((res) => {
        if (res.success) handleAppRouteChange()
        if (!res.success) {
          setLoader(false)
          res.error?.selectedUsers[0]
            ? message.error(res.error.selectedUsers[0])
            : res.response?.data?.error?.selectedUsers[0]
            ? message.error(res.response.data.error.selectedUsers[0])
            : res.data?.error?.message
            ? message.error(res.data.error.message)
            : res.response?.data?.error?.message &&
              message.error(res.response.data.error.message)
        }
      })
      .catch((error) => setLoader(false))
  }
  const disabled = isAppSelectVisible
    ? !activeAppId.length
    : isUserLicenseVisible
    ? !activeEmail.length
    : false
  let component
  useEffect(() => {
    if (orgId) {
      toggleAppSelect(false)
      toggleUserLicense(false)
      activeAppId.length && selectApp([])
    }
  }, [orgId])
  useEffect(() => {
    if (planStatus && !hasNoAccess) {
      setLoader(true)
      // planStatus.selectUserAction &&
      dispatch(getUsers(orgId))
        .then((res) => {
          if (!activeEmail.length) {
            const indexBy = findIndex(res.team, { hasAccess: true })
            !activeEmail.includes(res.team[indexBy].email) &&
              activeEmail.push(res.team[indexBy].email)
          }
          setLoader(false)
        })
        .catch((error) => setLoader(false))
      // planStatus.selectAppAction &&
      dispatch(getApps(orgId))
        .then((res) => setLoader(false))
        .catch((error) => setLoader(false))
    }
  }, [orgId, planStatus])
  component = (
    <TrialPlan
      toggleAppSelect={toggleAppSelect}
      toggleUserLicense={toggleUserLicense}
      selectUserAction={planStatus?.selectUserAction}
      selectAppAction={planStatus?.selectAppAction}
      loader={loader}
      planStatusMessage={planStatusMessage}
    />
  )
  if (hasNoAccess) {
    component = (
      <Wrapper loader={loader}>
        <div className='downgrade-message'>{hasNoAccessMessage}</div>
      </Wrapper>
    )
  }
  if (isAppSelectVisible && planStatus.selectAppAction) {
    component = (
      <AppSelect
        loader={loader}
        apps={apps}
        disabled={disabled}
        planStatus={planStatus}
        activeAppId={activeAppId}
        handleDoneCaseApps={handleDoneCaseApps}
        totalAllowedAppsInPlan={totalAllowedAppsInPlan}
        totalAllowedUsersInPlan={totalAllowedUsersInPlan}
        handleAppSelect={handleAppSelect}
        handleAppDeselect={handleAppDeselect}
        _getOrgCsrf={_getOrgCsrf}
        showHideQuoteModal={showHideQuoteModal}
      />
    )
  }
  if (isUserLicenseVisible && planStatus.selectUserAction) {
    component = (
      <UserSelect
        loader={loader}
        appTeam={appTeam}
        disabled={disabled}
        activeEmail={activeEmail}
        handleDoneCaseUsers={handleDoneCaseUsers}
        totalAllowedAppsInPlan={totalAllowedAppsInPlan}
        totalAllowedUsersInPlan={totalAllowedUsersInPlan}
        handleUserEmailSelect={handleUserEmailSelect}
        handleUserEmailDeselect={handleUserEmailDeselect}
      />
    )
  }
  if (questionPage)
    component = <Question toogleQuestionPage={toogleQuestionPage} />
  return (
    <>
      <IntegrateWrapper>
        <Col lg={20} className='height-full'>
          {component}
        </Col>
        <Col lg={4} className='height-full'>
          <CustomerSuccess
            toogleQuestionPage={toogleQuestionPage}
            questionPage={questionPage}
          />
        </Col>
      </IntegrateWrapper>
      <NewRequestQuoteForm
        setShowPricingModal={showHideQuoteModal}
        showPricingModal={requestQuoteVisible}
      />
    </>
  )
}
export default AccessManagement
