import React from 'react';
import { changeUrl } from 'redux/actions/common';
import Integration from 'components/IntegratePages';
import Layout from 'components/IntegratePages/layout';

interface IPage extends React.FC<any> {
  layout: typeof Layout,
  getInitialProps: ( context: any ) => Promise<any>
}

// eslint-disable-next-line react/jsx-props-no-spreading
const Page: IPage  = ( props ) => <Integration {...props} />
Page.layout = Layout
Page.getInitialProps = async ({ store, query }) => {
  if (query) {
    // eslint-disable-next-line no-param-reassign
    if (query.url === '/dashboard') query.parentType = 'dashboard'
    store.dispatch(changeUrl(query))
  }
  return { query }
}

export default Page
